import java.util.*;
public class ActivitySelection {
    public List<Integer> select(int[] start, int[] end) {
        int n = start.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a,b) -> end[a] - end[b]); // sort by finish time
        List<Integer> selected = new ArrayList<>();
        int lastEnd = -1;
        for (int i : idx) {
            if (start[i] >= lastEnd) {
                selected.add(i);
                lastEnd = end[i];
            }
        }
        return selected;
    }
    public static void main(String[] args) {
        int[] s={1,3,0,5,8,5}, e={2,4,6,7,9,9};
        System.out.println(new ActivitySelection().select(s,e));
    }
}

