#include <stdlib.h>
typedef struct {
    int s, e, i;
} Act;
int cmp(const void* a, const void* b) {
    return ((Act*)a)->e-((Act*)b)->e;
}
int main() {
    Act acts[]= { {
        1, 2, 0
    }, {3, 4, 1}, {0, 6, 2}, {5, 7, 3}, {8, 9, 4}, {5, 9, 5}};
    int n=6;
    qsort(acts, n, sizeof(Act), cmp);
    int lastEnd=-1;
    for (int i=0; i<n; i++) if (acts[i].s>=lastEnd) {
        printf("Activity %d ", acts[i].i);
        lastEnd=acts[i].e;
    }
    return 0;
}

